// The Worker's entry point (wrangler.jsonc "main"): the OpenNext build of the
// app (.open-next/worker.js, written by `opennextjs-cloudflare build`), plus
// the uploaded images (worker/uploads.ts) and the Cron Triggers
// (worker/crons.ts). See DEPLOY.md.

// Generated by the build, so it is missing before one (ts-expect-error would
// then fail after one).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNext from '../.open-next/worker.js'
import { WorkerEntrypoint } from 'cloudflare:workers'

import { errorSummary, logError, pathOf } from '../lib/log'
import { isInternalPath, readAdminStats } from './adminStats'
import { anonymousSession } from './anonymousSession'
import { canonicalRedirect } from './canonical'
import { cheapAnswer, forEdge, mayUseEdgeCache } from './edgeCache'
import { runCron, type FetchHandler, type WorkerEnv } from './crons'
import { assetsWithUploads, isUploadPath, serveUpload } from './uploads'

// The ISR revalidation queue (wrangler.jsonc durable_objects).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
export { DOQueueHandler } from '../.open-next/worker.js'

const app = openNext as FetchHandler

/**
 * Next marks ISR responses `s-maxage=<revalidate>, stale-while-revalidate` for
 * a CDN in front of it. There is none here (OpenNext's cache in R2 plays that
 * part), so browsers get what Vercel's CDN sent them instead: revalidate every
 * time (the same rule as n8builds-web's Worker).
 */
function forBrowsers(response: Response): Response {
    if (!response.headers.get('Cache-Control')?.includes('s-maxage')) return response
    const fresh = new Response(response.body, response)
    fresh.headers.set('Cache-Control', 'public, max-age=0, must-revalidate')
    return fresh
}

/** The cached entrypoint below, reached through ctx.exports. */
type CachedPagesExports = {
    exports: { CachedPages: { fetch(request: Request): Promise<Response> } }
}

/** OpenNext with ASSETS answering /uploads too, for the image optimizer. */
function withUploads(env: WorkerEnv): WorkerEnv {
    return { ...env, ASSETS: assetsWithUploads(env.ASSETS, env.UPLOADS) }
}

export default {
    async fetch(request, env, ctx) {
        try {
            // The old address and workers.dev forward to the site's own (worker/canonical.ts).
            const canonical = canonicalRedirect(request.url, env.PUBLIC_URL)
            if (canonical) return Response.redirect(canonical.location, canonical.status)
            // A signed-out visitor's session read is `null` without starting Next (worker/anonymousSession.ts).
            const anonymous = anonymousSession(request)
            if (anonymous) return anonymous
            // Service-only routes (worker/adminStats.ts) are never served to the internet.
            if (isInternalPath(new URL(request.url).pathname))
                return new Response('Not found', { status: 404 })
            if (isUploadPath(new URL(request.url).pathname))
                return await serveUpload(request, env.UPLOADS)
            const cheap = cheapAnswer(request)
            if (cheap) return cheap
            // The catalogue, images and the anonymous home page (worker/edgeCache.ts).
            if (env.PUBLIC_URL && mayUseEdgeCache(request, new URL(env.PUBLIC_URL).host)) {
                const cached = (ctx as ExecutionContext & CachedPagesExports).exports.CachedPages
                return await cached.fetch(request)
            }
            return forBrowsers(await app.fetch(request, withUploads(env), ctx))
        } catch (err) {
            // Next reports its own errors (instrumentation.ts onRequestError);
            // this is for a throw that escapes OpenNext or the uploads handler.
            logError({
                event: 'unhandled_exception',
                reason: 'worker_fetch_threw',
                route: pathOf(request.url),
                method: request.method,
                status: 500,
                error: errorSummary(err),
            })
            throw err
        }
    },

    async scheduled(controller, env, ctx) {
        const result = await runCron(app, controller.cron, withUploads(env), ctx)
        console.log(JSON.stringify({ event: 'cron', cron: controller.cron, ...result }))
    },
} satisfies ExportedHandler<WorkerEnv>

/**
 * What Cloudflare's cache sits in front of (wrangler.jsonc "exports"): a hit is
 * answered without running this code. The default entrypoint sends only
 * cacheable requests here (worker/edgeCache.ts).
 */
export class CachedPages extends WorkerEntrypoint<WorkerEnv> {
    async fetch(request: Request): Promise<Response> {
        return forEdge(
            request,
            forBrowsers(await app.fetch(request, withUploads(this.env), this.ctx))
        )
    }
}

/**
 * NetTrailers' totals for admin.n8builds.dev, over its NETTRAILERS_ADMIN
 * service binding (RPC; a named entrypoint has no public URL). Shape:
 * n8builds-admin's docs/APP-STATS.md. Totals only, never per-user data.
 */
export class AdminStats extends WorkerEntrypoint<WorkerEnv> {
    async stats() {
        return readAdminStats(app, withUploads(this.env), this.ctx)
    }
}
